process:
mesh = get_plugin('MeSHLookup')
query = (state.get('query') or state.get('text') or '').strip()
limit = state.get('limit') or 3
match = (state.get('match') or 'contains').strip()
if not query:
    __result__ = {'query': query, 'matches': [], 'error': "Missing 'query'"}
elif not mesh:
    __result__ = {'query': query, 'matches': [], 'error': 'MeSHLookup plugin unavailable'}
else:
    try:
        descriptors = mesh.lookup_descriptors(query, limit=limit, match=match)
        rows = []
        for d in descriptors:
            mesh_id = d.get('mesh_id') or ''
            synonyms = mesh.get_synonyms(mesh_id) if mesh_id else []
            hypernyms = mesh.get_hypernyms(mesh_id) if mesh_id else []
            rows.append({
                'mesh_id': mesh_id,
                'label': d.get('label') or '',
                'resource': d.get('resource') or '',
                'synonyms': synonyms,
                'hypernyms': hypernyms
            })
        __result__ = {'query': query, 'matches': rows}
    except Exception as e:
        __result__ = {'query': query, 'matches': [], 'error': str(e)}
